def transform(grid):
    # Compose the two 3x3 pattern fields using the marker as the output anchor.
    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]
    # The two fields are overlaid with the right field shifted one cell right;
    # where both contain foreground, preserve the left field's color.
    for r in range(h):
        for c in range(3):
            a, b = grid[r][c], grid[r][c+4]
            out[r][c+1] = a if a else b
            if a and b:
                out[r][c+1] = a
    for r in range(h):
        for c in range(8,w):
            if grid[r][c]: out[r][c-8] = grid[r][c]
    return out
